import java.util.*;

class Solution {
    public List<List<Integer>> fourSum(int[] nums, int target) {
        List<List<Integer>> result = new ArrayList<>();
        if (nums == null || nums.length < 4) return result;

        Arrays.sort(nums);
        int n = nums.length;

        for (int i = 0; i < n - 3; i++) {
            // Skip duplicates for first element
            if (i > 0 && nums[i] == nums[i - 1]) continue;

            // Early termination: smallest sum too large
            if ((long) nums[i] + nums[i+1] + nums[i+2] + nums[i+3] > target) break;
            // Skip: largest sum too small
            if ((long) nums[i] + nums[n-3] + nums[n-2] + nums[n-1] < target) continue;

            for (int j = i + 1; j < n - 2; j++) {
                // Skip duplicates for second element
                if (j > i + 1 && nums[j] == nums[j - 1]) continue;

                // Early termination for inner loop
                if ((long) nums[i] + nums[j] + nums[j+1] + nums[j+2] > target) break;
                if ((long) nums[i] + nums[j] + nums[n-2] + nums[n-1] < target) continue;

                int left = j + 1, right = n - 1;
                long newTarget = (long) target - nums[i] - nums[j];

                while (left < right) {
                    long sum = nums[left] + nums[right];

                    if (sum == newTarget) {
                        result.add(Arrays.asList(nums[i], nums[j], nums[left], nums[right]));
                        left++;
                        right--;
                        // Skip duplicates
                        while (left < right && nums[left] == nums[left - 1]) left++;
                        while (left < right && nums[right] == nums[right + 1]) right--;
                    } else if (sum < newTarget) {
                        left++;
                    } else {
                        right--;
                    }
                }
            }
        }

        return result;
    }
}

import java.util.*;

class Solution {
    public List<List<Integer>> fourSum(int[] nums, int target) {
        Arrays.sort(nums);
        return kSum(nums, target, 0, 4);
    }

    private List<List<Integer>> kSum(int[] nums, long target, int start, int k) {
        List<List<Integer>> result = new ArrayList<>();

        if (start >= nums.length) return result;

        // Average value check for early termination
        long avgVal = target / k;
        if (nums[start] > avgVal || nums[nums.length - 1] < avgVal) {
            return result;
        }

        if (k == 2) {
            return twoSum(nums, target, start);
        }

        for (int i = start; i < nums.length - k + 1; i++) {
            // Skip duplicates
            if (i > start && nums[i] == nums[i - 1]) continue;

            for (List<Integer> subset : kSum(nums, target - nums[i], i + 1, k - 1)) {
                List<Integer> combination = new ArrayList<>();
                combination.add(nums[i]);
                combination.addAll(subset);
                result.add(combination);
            }
        }

        return result;
    }

    private List<List<Integer>> twoSum(int[] nums, long target, int start) {
        List<List<Integer>> result = new ArrayList<>();
        int left = start, right = nums.length - 1;

        while (left < right) {
            long sum = nums[left] + nums[right];

            if (sum == target) {
                result.add(Arrays.asList(nums[left], nums[right]));
                left++;
                right--;
                while (left < right && nums[left] == nums[left - 1]) left++;
                while (left < right && nums[right] == nums[right + 1]) right--;
            } else if (sum < target) {
                left++;
            } else {
                right--;
            }
        }

        return result;
    }
}
